commandActions.command:
python3 -B - <<'PY'
from client import save
from payload import build_payload
class RecordingTransport:
    def put(self, path, body):
        self.request = (path, body)
        return {'ok': True}
for source, expected in [('Ada','Ada'),('  Ada  ','Ada'),('Ada Lovelace','Ada Lovelace'),('',''),(' \t\n',''),('\tAda\n','Ada'),('\u00a0Ada\u00a0','Ada')]:
    transport=RecordingTransport()
    result=save(transport,source)
    assert transport.request == ('/settings', {'display_name':expected})
    assert result == {'ok':True}
    print(repr(source),'->',repr(transport.request))
PY
